import {
  cleanup,
  fireEvent,
  render,
  screen,
  within,
} from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import PodcastPage from '../../client/src/features/podcast/PodcastPage';
import { PODCAST_CHANNELS } from '../../client/src/features/podcast/catalog';

beforeAll(() => {
  HTMLDialogElement.prototype.showModal = function () {
    this.setAttribute('open', '');
  };
  HTMLDialogElement.prototype.close = function () {
    this.removeAttribute('open');
  };
  window.matchMedia = jest.fn().mockReturnValue({ matches: false });
});
afterEach(cleanup);

function openPage(path = '/podcast') {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <PodcastPage />
    </MemoryRouter>,
  );
}

it('offers 20 distinct real video links in each of the seven requested channels', () => {
  openPage();
  expect(PODCAST_CHANNELS.map((channel) => channel.handle)).toEqual([
    'bbclearningenglish',
    'voalearningenglish',
    'EasyEnglishVideos',
    'LukesEnglishPodcast',
    'TheBritishEnglishPodcast',
    'TheDiaryOfACEO',
    'TED',
  ]);
  for (const channel of PODCAST_CHANNELS) {
    const row = screen.getByRole('region', {
      name: `Video của ${channel.name}`,
    });
    const links = within(row).getAllByRole('link');
    expect(links).toHaveLength(20);
    expect(new Set(channel.videos.map((video) => video.id)).size).toBe(20);
    channel.videos.forEach((video, index) => {
      expect(video.id).toMatch(/^[a-zA-Z0-9_-]{11}$/);
      expect(video.duration).toBeGreaterThan(0);
      expect(links[index].getAttribute('href')).toBe(`/podcast?v=${video.id}`);
    });
  }
  expect(screen.queryByRole('link', { name: 'Luyện nói' })).toBeNull();
});

it('opens the chosen video and removes the player on close, restoring page scrolling', () => {
  openPage();
  const video = PODCAST_CHANNELS[0].videos[0];
  fireEvent.click(screen.getByRole('link', { name: `Phát: ${video.title}` }));
  const dialog = screen.getByRole('dialog');
  expect(within(dialog).getByTitle(video.title).getAttribute('src')).toContain(
    `/embed/${video.id}?`,
  );
  expect(
    within(dialog)
      .getByRole('link', { name: /Mở trên YouTube/ })
      .getAttribute('href'),
  ).toBe(`https://www.youtube.com/watch?v=${video.id}`);
  expect(document.body.style.overflow).toBe('hidden');
  fireEvent.click(screen.getByRole('button', { name: 'Đóng video' }));
  expect(screen.queryByRole('dialog')).toBeNull();
  expect(screen.queryByTitle(video.title)).toBeNull();
  expect(document.body.style.overflow).toBe('');
});

it('opens a shared video URL and handles native Escape cancellation', () => {
  const video = PODCAST_CHANNELS[6].videos[19];
  openPage(`/podcast?v=${video.id}`);
  expect(screen.getByRole('dialog').textContent).toContain(video.title);
  fireEvent(
    screen.getByRole('dialog'),
    new Event('cancel', { bubbles: true, cancelable: true }),
  );
  expect(screen.queryByRole('dialog')).toBeNull();
});

it('keeps the catalog available for an unknown video without creating an arbitrary embed', () => {
  openPage('/podcast?v=unknown');
  expect(screen.getByRole('status').textContent).toContain(
    'không có trong danh sách',
  );
  expect(screen.queryByRole('dialog')).toBeNull();
  expect(screen.getAllByRole('region', { name: /^Video của / })).toHaveLength(7);
});

it('slides each channel independently and enables its previous button after scrolling', () => {
  openPage();
  const channel = PODCAST_CHANNELS[0];
  const row = screen.getByRole('region', { name: `Video của ${channel.name}` });
  const scrollBy = jest.fn();
  row.scrollBy = scrollBy;
  Object.defineProperty(row.firstElementChild, 'offsetWidth', { value: 280 });
  Object.defineProperties(row, {
    clientWidth: { configurable: true, value: 400 },
    scrollWidth: { configurable: true, value: 5800 },
    scrollLeft: { configurable: true, value: 292 },
  });
  fireEvent.click(
    screen.getByRole('button', { name: `Video tiếp theo của ${channel.name}` }),
  );
  expect(scrollBy).toHaveBeenCalledWith({ left: 292, behavior: 'smooth' });
  fireEvent.scroll(row);
  expect(
    (
      screen.getByRole('button', {
        name: `Video trước của ${channel.name}`,
      }) as HTMLButtonElement
    ).disabled,
  ).toBe(false);
  expect(
    (
      screen.getByRole('button', {
        name: 'Video trước của TED',
      }) as HTMLButtonElement
    ).disabled,
  ).toBe(true);
  fireEvent.keyDown(row, { key: 'ArrowLeft' });
  expect(scrollBy).toHaveBeenLastCalledWith({ left: -292, behavior: 'smooth' });
});
